// Sliding Window — O(n)
let minPrice = Infinity;
let maxProfit = 0;

for (let i = 0; i < prices.length; i++) {
  let price = prices[i];
  if (price < minPrice) {
    minPrice = price;
    __ll.note(`New min price: ${minPrice}`);
  } else {
    let profit = price - minPrice;
    if (profit > maxProfit) {
      maxProfit = profit;
      __ll.note(`New max profit: ${maxProfit}`);
    }
  }
}
return maxProfit;

// Sliding Window C++ — O(n)
#include <iostream>
#include <vector>

using namespace std;

int main() {
  int minPrice = 2147483647;
  int maxProfit = 0;

  for (int i = 0; i < prices.size(); i++) {
    int price = prices[i];
    if (price < minPrice) {
      minPrice = price;
      __ll_note("New min price: " + __ll_to_json(minPrice));
    } else {
      int profit = price - minPrice;
      if (profit > maxProfit) {
        maxProfit = profit;
        __ll_note("New max profit: " + __ll_to_json(maxProfit));
      }
    }
  }
  return 0;
}
